using System.Security.Claims; using Astraea.Application; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace Astraea.Web;
[ApiController][Route("api/auth")] public sealed class AuthController(IAuthService service):ControllerBase { [HttpPost("register")] public Task<AuthResponseDto> Register(RegisterUserRequest r,CancellationToken ct)=>service.RegisterAsync(r,ct); [HttpPost("login")] public Task<AuthResponseDto> Login(LoginRequest r,CancellationToken ct)=>service.LoginAsync(r,ct); [Authorize][HttpPost("change-password")] public Task ChangePassword(ChangePasswordRequest r,CancellationToken ct)=>service.ChangePasswordAsync(Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!),r,ct); }
[ApiController][Authorize(Roles="Learner")][Route("api/learner/mentors")] public sealed class LearnerMentorsController(IMentorService service):ControllerBase { Guid Me=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!); [HttpGet]public Task<IReadOnlyCollection<MentorLearnerDto>> Get(CancellationToken ct)=>service.GetLearnerMentorsAsync(Me,ct);[HttpPost("invite")]public async Task<ActionResult<MentorLearnerDto>> Invite(MentorInviteRequest r,CancellationToken ct){try{return Ok(await service.InviteMentorAsync(Me,r.Email,ct));}catch(InvalidOperationException ex){return BadRequest(ex.Message);}}[HttpDelete("invitations/{id:guid}")]public Task Cancel(Guid id,CancellationToken ct)=>service.CancelInvitationAsync(id,Me,ct);[HttpPost("{id:guid}/revoke")]public Task Revoke(Guid id,CancellationToken ct)=>service.RevokeAccessAsync(id,Me,ct); }
[ApiController][Authorize(Roles="Learner")][Route("api/skills")] public sealed class SkillsController(ISkillService service):ControllerBase { Guid Me=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!); [HttpGet] public Task<IReadOnlyCollection<CelestialNodeDto>> Get(CancellationToken ct)=>service.GetSkillsAsync(Me,ct); [HttpPost]public Task<CelestialNodeDto> Create(CreateSkillRequest r,CancellationToken ct)=>service.CreateSkillAsync(Me,r,ct); }
[ApiController][Authorize(Roles="Learner")][Route("api/reports")] public sealed class ReportsController(IReportService service):ControllerBase { [HttpGet] public Task<LearnerReportDto> Get(CancellationToken ct)=>service.GetLearnerReportAsync(Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!),ct); }
[ApiController][Authorize(Roles="Learner")][Route("api/learner/reminders")] public sealed class LearnerRemindersController(IReminderService service):ControllerBase { Guid Me=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet]public Task<IReadOnlyCollection<MentorReminderDto>> Get(CancellationToken ct)=>service.GetUnreadForLearnerAsync(Me,ct);[HttpPost("{id:guid}/viewed")]public Task Viewed(Guid id,CancellationToken ct)=>service.MarkReadAsync(Me,id,ct); }
[ApiController][Authorize(Roles="Mentor")][Route("api/mentor")] public sealed class MentorPortalController(IMentorService service,IReminderService reminders):ControllerBase { Guid Me=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpGet("invitations")]public Task<IReadOnlyCollection<MentorLearnerDto>> Invitations(CancellationToken ct)=>service.GetPendingInvitationsForMentorAsync(Me,ct);[HttpPost("invitations/{id:guid}/accept")]public Task<AuthResponseDto> Accept(Guid id,CancellationToken ct)=>service.AcceptInvitationAsync(id,Me,ct);[HttpPost("invitations/{id:guid}/decline")]public Task Decline(Guid id,CancellationToken ct)=>service.DeclineInvitationAsync(id,Me,ct);[HttpGet("mentees")]public Task<IReadOnlyCollection<LearnerSummaryDto>> Mentees(CancellationToken ct)=>service.GetActiveMenteesAsync(Me,ct);[HttpGet("learners/{learnerId:guid}")]public Task<LearnerDashboardDto> Dashboard(Guid learnerId,CancellationToken ct)=>service.GetLearnerDashboardReadOnlyAsync(Me,learnerId,ct);[HttpPost("learners/{learnerId:guid}/fading-reminder")]public Task SendReminder(Guid learnerId,CancellationToken ct)=>reminders.SendFadingSkillReminderAsync(Me,learnerId,ct); }
